-- 08e03a2b | ما هو التفسير بالرأي، وما ضوابطه؟
UPDATE qa_questions SET
  answer = 'التفسيرُ بالرأي عند السيوطي في الإتقان ليس مأخذًا مستقلًّا يُبتدأ به، بل آخرُ مراتب الطلب بعد استنفاد ما قبله؛ فالمفسّر «مَنْ أَرَادَ تَفْسِيرَ الْكِتَابِ الْعَزِيزِ، طَلَبَهُ أَوَّلًا مِنَ الْقُرْآنِ»، «فَإِنْ أَعْيَاهُ ذَلِكَ طَلَبَهُ مِنَ السُّنَّةِ فَإِنَّهَا شَارِحَةٌ لِلْقُرْآنِ وَمُوَضَّحَةٌ لَهُ»، «فإن لم يجده في السُّنَّةِ رَجَعَ إِلَى أَقْوَالِ الصَّحَابَةِ»، ثم «الثَّالِثُ: الْأَخْذُ بِمُطْلَقِ اللُّغَةِ، فَإِنَّ الْقُرْآنَ نَزَلَ بِلِسَانٍ عَرَبِيٍّ»، ثم «التَّفْسِيرُ بِالْمُقْتَضَى مِنْ مَعْنَى الْكَلَامِ وَالْمُقْتَضَبِ مِنْ قُوَّةِ الشَّرْعِ». والمنصوصُ في تحريم قسمِه المذموم: «وَلَا يَجُوزُ تَفْسِيرُ الْقُرْآنِ بِمُجَرَّدِ الرَّأْيِ وَالِاجْتِهَادِ مِنْ غَيْرِ أَصْلٍ»؛ فالممنوعُ هو الرأيُ الذي لا يستند إلى أصل، ومنه حديثُ: «مَنْ تَكَلَّمَ فِي الْقُرْآنِ بِرَأْيِهِ، فَأَصَابَ فَقَدْ أخطأ». وحملَه البيهقيُّ — كما نقل عنه السيوطي — على «الرَّأْيَ الَّذِي يَغْلِبُ مِنْ غَيْرِ دَلِيلٍ قَامَ عَلَيْهِ»، «وَأَمَّا الَّذِي يَسْنِدُهُ بُرْهَانٌ، فَالْقَوْلُ بِهِ جَائِزٌ». ومن شرط المفسّر عند السيوطي أن يكون عالمًا بلغة العرب، وفيه عن مالك: «لَا أَوُتَى بِرَجُلٍ غَيْرِ عَالِمٍ بِلُغَةِ الْعَرَبِ يُفَسِّرُ كِتَابَ اللَّهِ إِلَّا جَعَلْتُهُ نَكَالًا».',
  reference = 'الإتقان في علوم القرآن للسيوطي، ت محمد أبو الفضل إبراهيم (٤ أجزاء): ج٤/ص٢٠٠ و٢٠٩–٢١٠ (النوع الثامن والسبعون: معرفة شروط المفسر وآدابه) | الكلمات المفتاحية: التفسير بالرأي',
  evidence = 'الإتقان ج٤/ص٢٠٠ يرتّب مآخذ التفسير ترتيبًا لازمًا: «مَنْ أَرَادَ تَفْسِيرَ الْكِتَابِ الْعَزِيزِ، طَلَبَهُ أَوَّلًا مِنَ الْقُرْآنِ»، «فَإِنْ أَعْيَاهُ ذَلِكَ طَلَبَهُ مِنَ السُّنَّةِ فَإِنَّهَا شَارِحَةٌ لِلْقُرْآنِ وَمُوَضَّحَةٌ لَهُ»، «فإن لم يجده في السُّنَّةِ رَجَعَ إِلَى أَقْوَالِ الصَّحَابَةِ». ثم نصَّ ج٤/ص٢١٠ على القيد الأكبر: «وَلَا يَجُوزُ تَفْسِيرُ الْقُرْآنِ بِمُجَرَّدِ الرَّأْيِ وَالِاجْتِهَادِ مِنْ غَيْرِ أَصْلٍ»، واستدلّ بحديث: «مَنْ تَكَلَّمَ فِي الْقُرْآنِ بِرَأْيِهِ، فَأَصَابَ فَقَدْ أخطأ» ⇐ ونقل عن البيهقي حملَه على «الرَّأْيَ الَّذِي يَغْلِبُ مِنْ غَيْرِ دَلِيلٍ قَامَ عَلَيْهِ»، «وَأَمَّا الَّذِي يَسْنِدُهُ بُرْهَانٌ، فَالْقَوْلُ بِهِ جَائِزٌ». وأدواتُ المأخذ الرابع منصوصةٌ ج٤/ص٢٠٩: «الثَّالِثُ: الْأَخْذُ بِمُطْلَقِ اللُّغَةِ، فَإِنَّ الْقُرْآنَ نَزَلَ بِلِسَانٍ عَرَبِيٍّ»، و«التَّفْسِيرُ بِالْمُقْتَضَى مِنْ مَعْنَى الْكَلَامِ وَالْمُقْتَضَبِ مِنْ قُوَّةِ الشَّرْعِ». ⚠️ وإطلاقُ ‹جائز بضوابط› بلا ترتيبِ المآخذ يُخِلّ بأصل المسألة عند السيوطي؛ فالرأيُ ليس مأخذًا مستقلًّا يُبتدأ به، بل آخرُ المآخذ بعد القرآن والسنة وأقوال الصحابة واللغة.',
  verification_status = 'verified'
WHERE id = '08e03a2b-0d54-411e-841d-f74a7865511a'
  AND reference = 'كتب مناهج التفسير | الكلمات المفتاحية: التفسير بالرأي'
  AND evidence = 'مبحث معروف في مناهج التفسير، محل تفصيل بين العلماء.'
  AND answer = 'تفسير القرآن بالاجتهاد العقلي المبني على أدوات اللغة والشريعة، وهو جائز بضوابط (كمعرفة اللغة والسياق وعدم مخالفة نص أو إجماع)، بخلاف التفسير بمحض الهوى بلا أداة علمية وهو محرَّم.';

-- d853819b | ما أشهر كتب التفسير بالمأثور؟
UPDATE qa_questions SET
  answer = 'أشهرُ كتب التفسير بالمأثور — بتعداد السيوطي في الإتقان — طبقتان: طبقةُ التفاسير المسنَدة الأولى: «ثُمَّ بَعْدَ هَذِهِ الطَّبَقَةِ أُلِّفَتْ تَفَاسِيرُ تَجْمَعُ أَقْوَالَ الصَّحَابَةِ وَالتَّابِعِينَ كَتَفْسِيرِ سُفْيَانَ بْنِ عُيَيْنَةَ وَوَكِيعِ بْنِ الْجَرَّاحِ وَشُعْبَةَ بْنِ الْحَجَّاجِ» ومعهم يزيدُ بن هارون وعبدُ الرزاق وإسحاقُ بن راهويه وأبو بكر بن أبي شيبة؛ ثم طبقةُ من بعدهم: «وَبَعْدَهُمِ ابْنُ جَرِيرٍ الطَّبَرِيُّ وَكِتَابُهُ أَجَلُّ التَّفَاسِيرِ وَأَعْظَمُهَا ثُمَّ ابْنُ أَبِي حَاتِمٍ وَابْنُ مَاجَهْ وَالْحَاكِمُ وَابْنُ مَرْدَوَيْهِ» وأبو الشيخ وابنُ المنذر. وضابطُ كونها ‹مأثورة› أنها مسنَدة: «وَكُلُّهَا مُسْنَدَةٌ إِلَى الصَّحَابَةِ وَالتَّابِعِينَ وَأَتْبَاعِهِمْ وَلَيْسَ فِيهَا غَيْرَ ذَلِكَ إِلَّا ابْنُ جَرِيرٍ» — فإنه يزيد على النقل توجيهَ الأقوال وترجيحَ بعضها. وأولاها بالتعويل عند السيوطي: «تَفْسِيرُ الْإِمَامِ أَبِي جَعْفَرِ بْنِ جَرِيرٍ الطَّبَرِيِّ الَّذِي أَجْمَعَ الْعُلَمَاءُ الْمُعْتَبَرُونَ عَلَى أَنَّهُ لَمْ يُؤَلَّفْ فِي التَّفْسِيرِ مِثْلُهُ»، ونقل عن النووي: «كِتَابُ ابْنِ جَرِيرٍ فِي التَّفْسِيرِ لَمْ يُصَنِّفْ أَحَدٌ مِثْلَهُ». وتنبيهان: الأولُ أن تفسير القرطبي ليس من هذه الطبقة عند السيوطي، بل جعله مثالَ التفسير الفقهيّ: «وَالْفَقِيهُ يَكَادُ يَسْرُدُ فِيهِ الْفِقْهَ مِنْ بَابِ الطَّهَارَةِ إِلَى أُمَّهَاتِ الْأَوْلَادِ ... كَالْقُرْطُبِيِّ»؛ والثاني أن ما بعد الطبقة المسنَدة دخله الضعف باختصار الأسانيد: «ثُمَّ أَلَّفَ فِي التَّفْسِيرِ خَلَائِقُ فَاخْتَصَرُوا الْأَسَانِيدَ وَنَقَلُوا الْأَقْوَالَ بَتْرًا فَدَخَلَ مِنْ هُنَا الدَّخِيلُ وَالْتَبَسَ الصَّحِيحُ بِالْعَلِيلِ».',
  reference = 'الإتقان في علوم القرآن للسيوطي، ت محمد أبو الفضل إبراهيم (٤ أجزاء): ج٤/ص٢٤٢–٢٤٤ (النوع الثمانون: طبقات المفسرين) | الكلمات المفتاحية: التفسير بالمأثور، كتب التفسير',
  evidence = 'الإتقان ج٤/ص٢٤٢ يسرد التفاسيرَ المسنَدة بأسمائها: «ثُمَّ بَعْدَ هَذِهِ الطَّبَقَةِ أُلِّفَتْ تَفَاسِيرُ تَجْمَعُ أَقْوَالَ الصَّحَابَةِ وَالتَّابِعِينَ كَتَفْسِيرِ سُفْيَانَ بْنِ عُيَيْنَةَ وَوَكِيعِ بْنِ الْجَرَّاحِ وَشُعْبَةَ بْنِ الْحَجَّاجِ»، ثم «وَبَعْدَهُمِ ابْنُ جَرِيرٍ الطَّبَرِيُّ وَكِتَابُهُ أَجَلُّ التَّفَاسِيرِ وَأَعْظَمُهَا ثُمَّ ابْنُ أَبِي حَاتِمٍ وَابْنُ مَاجَهْ وَالْحَاكِمُ وَابْنُ مَرْدَوَيْهِ»، وضابطُها: «وَكُلُّهَا مُسْنَدَةٌ إِلَى الصَّحَابَةِ وَالتَّابِعِينَ وَأَتْبَاعِهِمْ وَلَيْسَ فِيهَا غَيْرَ ذَلِكَ إِلَّا ابْنُ جَرِيرٍ». وج٤/ص٢٤٤ صريحٌ في المقدَّم منها: «تَفْسِيرُ الْإِمَامِ أَبِي جَعْفَرِ بْنِ جَرِيرٍ الطَّبَرِيِّ الَّذِي أَجْمَعَ الْعُلَمَاءُ الْمُعْتَبَرُونَ عَلَى أَنَّهُ لَمْ يُؤَلَّفْ فِي التَّفْسِيرِ مِثْلُهُ»، وفيه عن النووي: «كِتَابُ ابْنِ جَرِيرٍ فِي التَّفْسِيرِ لَمْ يُصَنِّفْ أَحَدٌ مِثْلَهُ». 🔑 وتصحيحٌ لازم: عدُّ ‹القرطبي› في كتب المأثور خطأٌ على تصنيف السيوطي نفسِه، فقد جعله ج٤/ص٢٤٣ مثالَ التفسير الفقهيّ: «وَالْفَقِيهُ يَكَادُ يَسْرُدُ فِيهِ الْفِقْهَ مِنْ بَابِ الطَّهَارَةِ إِلَى أُمَّهَاتِ الْأَوْلَادِ ... كَالْقُرْطُبِيِّ»؛ ولم يَرِد ‹ابن كثير› ولا ‹الدر المنثور› في تعداد هذا الموضع أصلًا. وعلّةُ ما بعد الطبقة المسنَدة منصوصةٌ ج٤/ص٢٤٢: «ثُمَّ أَلَّفَ فِي التَّفْسِيرِ خَلَائِقُ فَاخْتَصَرُوا الْأَسَانِيدَ وَنَقَلُوا الْأَقْوَالَ بَتْرًا فَدَخَلَ مِنْ هُنَا الدَّخِيلُ وَالْتَبَسَ الصَّحِيحُ بِالْعَلِيلِ».',
  verification_status = 'verified'
WHERE id = 'd853819b-e2be-4f7a-9dc8-2ae9806212f5'
  AND reference = 'كتب مناهج التفسير | الكلمات المفتاحية: التفسير بالمأثور، كتب التفسير'
  AND evidence = 'تصنيف متعارف عليه في مناهج التفسير عند علماء علوم القرآن.'
  AND answer = 'من أشهرها: تفسير الطبري (جامع البيان)، وتفسير ابن كثير، وتفسير القرطبي، والدر المنثور للسيوطي — وهي تفاسير تعتمد أساسًا على تفسير القرآن بالقرآن والسنة وأقوال الصحابة والتابعين.';

-- 6a9b9f39 | ما هي طبقات المفسرين تاريخيًا؟
UPDATE qa_questions SET
  answer = 'طبقاتُ المفسرين عند السيوطي في الإتقان مرتَّبةٌ على الطبقات وأصحابها: (١) طبقةُ الصحابة: «اشْتُهِرَ بِالتَّفْسِيرِ مِنَ الصَّحَابَةِ عَشَرَةُ: الْخُلَفَاءُ الْأَرْبَعَةُ، وابن مسعود وابن عَبَّاسٍ وَأُبَيُّ بْنُ كَعْبٍ وَزَيْدُ بْنُ ثَابِتٍ وَأَبُو مُوسَى الْأَشْعَرِيُّ وَعَبْدُ اللَّهِ بْنُ الزُّبَيْرِ»، وأكثرُهم روايةً عليٌّ وابنُ مسعود وابنُ عباس، أمّا الثلاثةُ الأُوَل من الخلفاء فـ«وَالرِّوَايَةُ عَنِ الثَّلَاثَةِ نَزِرَةٌ جَدًّا». (٢) طبقةُ قدماء التابعين — مجاهد وسعيد بن جبير وعكرمة وقتادة والضحّاك وغيرهم: «فَهَؤُلَاءِ قُدَمَاءُ الْمُفَسِّرِينَ وَغَالِبُ أَقْوَالِهِمْ تَلَقَّوْهَا عَنِ الصَّحَابَةِ». (٣) طبقةُ التفاسير المسنَدة الجامعة لأقوال الصحابة والتابعين: سفيانُ بن عيينة ووكيعٌ وشعبةُ وعبدُ الرزاق، ثم ابنُ جرير الطبري «وَكِتَابُهُ أَجَلُّ التَّفَاسِيرِ وَأَعْظَمُهَا»، ثم ابنُ أبي حاتم والحاكمُ وابنُ مردويه وابنُ المنذر. (٤) طبقةُ من اختصر الأسانيد فدخل النقصُ: «ثُمَّ أَلَّفَ فِي التَّفْسِيرِ خَلَائِقُ فَاخْتَصَرُوا الْأَسَانِيدَ وَنَقَلُوا الْأَقْوَالَ بَتْرًا فَدَخَلَ مِنْ هُنَا الدَّخِيلُ وَالْتَبَسَ الصَّحِيحُ بِالْعَلِيلِ». (٥) طبقةُ التفاسير المتخصصة بالفنون: «ثُمَّ صَنَّفَ بَعْدَ ذَلِكَ قَوْمٌ بَرَعُوا فِي عُلُومٍ فَكَانَ كُلٌّ مِنْهُمْ يَقْتَصِرُ فِي تَفْسِيرِهِ عَلَى الْفَنِّ الَّذِي يَغْلِبُ عَلَيْهِ» — فالنحويُّ همُّه الإعراب، والإخباريُّ القصص، والفقيهُ يسرد الفقه، وصاحبُ العلوم العقلية يملأ تفسيره بأقوال الحكماء.',
  reference = 'الإتقان في علوم القرآن للسيوطي، ت محمد أبو الفضل إبراهيم (٤ أجزاء): ج٤/ص٢٣٣ و٢٤٢–٢٤٣ (النوع الثمانون: طبقات المفسرين) | الكلمات المفتاحية: تاريخ التفسير',
  evidence = 'الإتقان ج٤/ص٢٣٣ يفتتح طبقاتِ المفسرين بطبقة الصحابة معدودةً: «اشْتُهِرَ بِالتَّفْسِيرِ مِنَ الصَّحَابَةِ عَشَرَةُ: الْخُلَفَاءُ الْأَرْبَعَةُ، وابن مسعود وابن عَبَّاسٍ وَأُبَيُّ بْنُ كَعْبٍ وَزَيْدُ بْنُ ثَابِتٍ وَأَبُو مُوسَى الْأَشْعَرِيُّ وَعَبْدُ اللَّهِ بْنُ الزُّبَيْرِ»، مع تفاوتٍ منصوص في المرويّ عنهم: «وَالرِّوَايَةُ عَنِ الثَّلَاثَةِ نَزِرَةٌ جَدًّا». ثم طبقةُ التابعين ج٤/ص٢٤٢: «فَهَؤُلَاءِ قُدَمَاءُ الْمُفَسِّرِينَ وَغَالِبُ أَقْوَالِهِمْ تَلَقَّوْهَا عَنِ الصَّحَابَةِ»، ثم طبقةُ التفاسير المسنَدة، ثم من اختصر الأسانيد: «ثُمَّ أَلَّفَ فِي التَّفْسِيرِ خَلَائِقُ فَاخْتَصَرُوا الْأَسَانِيدَ وَنَقَلُوا الْأَقْوَالَ بَتْرًا فَدَخَلَ مِنْ هُنَا الدَّخِيلُ وَالْتَبَسَ الصَّحِيحُ بِالْعَلِيلِ»، ثم طبقةُ التفاسير المتخصصة ج٤/ص٢٤٣: «ثُمَّ صَنَّفَ بَعْدَ ذَلِكَ قَوْمٌ بَرَعُوا فِي عُلُومٍ فَكَانَ كُلٌّ مِنْهُمْ يَقْتَصِرُ فِي تَفْسِيرِهِ عَلَى الْفَنِّ الَّذِي يَغْلِبُ عَلَيْهِ». ⚠️ فالتقسيمُ عند السيوطي بالطبقات وأصحابها لا بثنائيّة ‹مأثور ثم رأي منضبط›، والتخصّصُ بالفنون آخرُ الطبقات لا مرتبةً ثالثة مستقلّة عن المصنِّفين.',
  verification_status = 'verified'
WHERE id = '6a9b9f39-6a89-402e-810d-e46277fb2fc3'
  AND reference = 'كتب مناهج التفسير | الكلمات المفتاحية: تاريخ التفسير'
  AND evidence = 'تطور تاريخي موثَّق في كتب مناهج التفسير.'
  AND answer = 'التفسير بالمأثور أولاً (تفسير القرآن بالقرآن ثم بالسنة ثم بأقوال الصحابة والتابعين)، ثم توسّع لاحقًا للتفسير بالرأي المنضبط، ثم ظهرت تفاسير متخصصة (فقهية، لغوية، بلاغية، علمية) عبر القرون اللاحقة.';

-- a5a1a02d | ما معنى "غريب القرآن" في علوم القرآن؟
UPDATE qa_questions SET
  answer = '«غريب القرآن» نوعٌ مستقلٌّ من علوم القرآن عند السيوطي في الإتقان، وهو معرفةُ الألفاظ التي خفي معناها فتحتاج إلى بيانٍ من كلام العرب، وقد «أَفْرَدَهُ بِالتَّصْنِيفِ خَلَائِقُ لَا يُحْصَوْنَ: مِنْهُمْ أَبُو عُبَيْدَةَ وَأَبُو عُمَرَ الزَّاهِدُ وَابْنُ دُرَيْدٍ»، ومن أشهرها كتابُ العزيزيّ، «وَمِنْ أَحْسَنِهَا الْمُفْرَدَاتُ لِلرَّاغِبِ». وحكمُ العناية به منصوص: «وَيَنْبَغِي الِاعْتِنَاءُ بِهِ». ومرجعُ بيانه كلامُ العرب وأشعارُها؛ قال ابن عباس: «الشِّعْرُ دِيوَانُ الْعَرَبِ فَإِذَا خَفِيَ عَلَيْنَا الْحَرْفُ مِنَ الْقُرْآنِ الَّذِي أَنْزَلَهُ اللَّهُ بِلُغَةِ الْعَرَبِ رَجَعْنَا إِلَى دِيوَانِهَا»، وقال: «إِذَا سَأَلْتُمُونِي عَنْ غَرِيبِ الْقُرْآنِ فَالْتَمِسُوهُ فِي الشِّعْرِ». وقد ساق السيوطي في هذا النوع تفسيرَ الغريب مسنَدًا إلى ابن عباس: «هَذَا لَفْظُ ابْنِ عَبَّاسٍ أَخْرَجَهُ ابْنُ جَرِيرٍ وَابْنُ أَبِي حَاتِمٍ فِي تَفْسِيرِهِمَا مُفَرَّقًا فَجَمَعْتُهُ»، ونبّه إلى حدّه: «وَهُوَ وَإِنْ لَمْ يَسْتَوْعِبْ غَرِيبَ الْقُرْآنِ فَقَدْ أَتَى عَلَى جُمْلَةٍ صَالِحَةٍ مِنْهُ». ويُفرَّق بين هذا النوع وبين نوعٍ آخرَ مستقلٍّ عنده هو ما وقع في القرآن بغير لغة الحجاز، فليست الغرابةُ مردودةً إلى اللهجات وحدها.',
  reference = 'الإتقان في علوم القرآن للسيوطي، ت محمد أبو الفضل إبراهيم (٤ أجزاء): ج٢/ص٣ و٥٧ و٦٧ (النوع السادس والثلاثون: معرفة غريبه) | الكلمات المفتاحية: غريب القرآن',
  evidence = 'الإتقان ج٢/ص٣ يُفرد لغريب القرآن نوعًا مستقلًّا، ويسمّي مصنِّفيه: «أَفْرَدَهُ بِالتَّصْنِيفِ خَلَائِقُ لَا يُحْصَوْنَ: مِنْهُمْ أَبُو عُبَيْدَةَ وَأَبُو عُمَرَ الزَّاهِدُ وَابْنُ دُرَيْدٍ»، «وَمِنْ أَحْسَنِهَا الْمُفْرَدَاتُ لِلرَّاغِبِ»، وحكمُه: «وَيَنْبَغِي الِاعْتِنَاءُ بِهِ». ومرجعُ بيانه عند ابن عباس كلامُ العرب، ج٢/ص٦٧: «الشِّعْرُ دِيوَانُ الْعَرَبِ فَإِذَا خَفِيَ عَلَيْنَا الْحَرْفُ مِنَ الْقُرْآنِ الَّذِي أَنْزَلَهُ اللَّهُ بِلُغَةِ الْعَرَبِ رَجَعْنَا إِلَى دِيوَانِهَا»، ومنه: «إِذَا سَأَلْتُمُونِي عَنْ غَرِيبِ الْقُرْآنِ فَالْتَمِسُوهُ فِي الشِّعْرِ». وأصلُ ما جُمع فيه مسنَدٌ إلى ابن عباس ج٢/ص٥٧: «هَذَا لَفْظُ ابْنِ عَبَّاسٍ أَخْرَجَهُ ابْنُ جَرِيرٍ وَابْنُ أَبِي حَاتِمٍ فِي تَفْسِيرِهِمَا مُفَرَّقًا فَجَمَعْتُهُ»، بقيدٍ منصوص: «وَهُوَ وَإِنْ لَمْ يَسْتَوْعِبْ غَرِيبَ الْقُرْآنِ فَقَدْ أَتَى عَلَى جُمْلَةٍ صَالِحَةٍ مِنْهُ». 🚩 ونسبةُ المصنَّف إلى ‹ابن قتيبة› لا وجود لها في تعداد السيوطي في هذا الموضع، والمسمَّون فيه غيرُه؛ وتعليلُ الغرابة بـ‹لهجاتٍ عربية غير مشهورة› ليس من هذا النوع، فما وقع بغير لغة الحجاز نوعٌ آخرُ مستقلٌّ عنده.',
  verification_status = 'verified'
WHERE id = 'a5a1a02d-f3a4-4c2a-914c-dcef2b9d196c'
  AND reference = 'كتب غريب القرآن | الكلمات المفتاحية: غريب القرآن'
  AND evidence = 'مبحث مستقل في علوم القرآن، له كتب مصنَّفة كغريب القرآن لابن قتيبة.'
  AND answer = 'الألفاظ القرآنية التي خفي معناها على غير المتخصصين في اللغة العربية لقلة استعمالها أو لكونها من لهجات عربية غير مشهورة، وقد أُفردت لها مصنَّفات مستقلة لشرحها.';

-- f244abe0 | من هم أشهر الصحابة الفقهاء؟
UPDATE qa_questions SET
  answer = 'أشهرُ التعدادات المسنَدة لفقهاء الصحابة نقلُ مسروق الذي يرويه الذهبي في سير أعلام النبلاء عن الشعبي: «كَانَ أَصْحَابُ الفَتْوَى مِنْ أَصْحَابِ رَسُوْلِ اللهِ ... عُمَرُ، وَعَلِيٌّ، وَابْنُ مَسْعُوْدٍ، وَزَيْدٌ، وَأُبَيٌّ، وَأَبُو مُوْسَى» — وهم ستّة: عمر بن الخطاب، وعلي بن أبي طالب، وعبد الله بن مسعود، وزيد بن ثابت، وأُبيّ بن كعب، وأبو موسى الأشعري رضي الله عنهم. ويُضاف إليهم معاذُ بن جبل بمأخذٍ آخر هو حديثُ أنس عند الترمذي (٣٧٩٠): «وَأَعْلَمُهُمْ بِالحَلَالِ وَالحَرَامِ مُعَاذُ بْنُ جَبَلٍ، وَأَفْرَضُهُمْ زَيْدُ بْنُ ثَابِتٍ، وَأَقْرَؤُهُمْ أُبَيُّ بْنُ كَعْبٍ»، وقد قال الترمذي عقبه: «هَذَا حَدِيثٌ غَرِيبٌ لَا نَعْرِفُهُ مِنْ حَدِيثِ قَتَادَةَ إِلَّا مِنْ هَذَا الوَجْهِ»، ونبّه إلى أنّ «وَالمَشْهُورُ حَدِيثُ أَبِي قِلَابَةَ». فهذه التعدادات تعدادُ اشتهارٍ بالفتوى لا حصرٌ لمن كان يفتي من الصحابة، ويلزم في نسبة كلّ اسمٍ ردُّه إلى موضعه: فعبدُ الله بن عباس رضي الله عنه إنما اشتُهر في تعداد السيوطي بالتفسير، ومعاذٌ مأخذُه الحديثُ المذكور لا نقلُ مسروق.',
  reference = 'سير أعلام النبلاء للذهبي، بإشراف شعيب الأرناؤوط (مؤسسة الرسالة، ط٣ ١٤٠٥هـ): ج٢/ص٤٣٣ (ترجمة زيد بن ثابت)، ومعه سنن الترمذي ٣٧٩٠ (ت أحمد محمد شاكر وآخرين) | الكلمات المفتاحية: فقهاء الصحابة',
  evidence = 'سيرُ أعلام النبلاء ج٢/ص٤٣٣ يسند التعدادَ إلى نقلٍ عن مسروق بإسناد الشعبي: «كَانَ أَصْحَابُ الفَتْوَى مِنْ أَصْحَابِ رَسُوْلِ اللهِ ... عُمَرُ، وَعَلِيٌّ، وَابْنُ مَسْعُوْدٍ، وَزَيْدٌ، وَأُبَيٌّ، وَأَبُو مُوْسَى» — فهم ستّةٌ، وفيهم أُبيُّ بن كعب وأبو موسى الأشعري. وأمّا معاذُ بن جبل فمأخذُ تخصيصه بالفقه حديثُ أنس عند الترمذي (٣٧٩٠): «وَأَعْلَمُهُمْ بِالحَلَالِ وَالحَرَامِ مُعَاذُ بْنُ جَبَلٍ، وَأَفْرَضُهُمْ زَيْدُ بْنُ ثَابِتٍ، وَأَقْرَؤُهُمْ أُبَيُّ بْنُ كَعْبٍ»، وحكمُ الترمذي عليه منصوصٌ في الموضع: «هَذَا حَدِيثٌ غَرِيبٌ لَا نَعْرِفُهُ مِنْ حَدِيثِ قَتَادَةَ إِلَّا مِنْ هَذَا الوَجْهِ»، وأنّ «وَالمَشْهُورُ حَدِيثُ أَبِي قِلَابَةَ». 🚩 والتعدادُ السابق أسقط أُبيًّا وأبا موسى وهما في نقل مسروق، وأدرج ابنَ عباس ومعاذًا وليسا فيه — وابنُ عباس إنما اشتُهر بالتفسير في تعداد السيوطي، ومعاذٌ مأخذُه الحديثُ المذكور لا نقلُ مسروق؛ فالتعدادُ يلزمه إسنادُ كلِّ اسمٍ إلى موضعه لا خلطُ المصادر.',
  verification_status = 'verified'
WHERE id = 'f244abe0-9f4e-469a-b2a9-e71ddc4d0dc9'
  AND reference = 'كتب طبقات الفقهاء | الكلمات المفتاحية: فقهاء الصحابة'
  AND evidence = 'مذكورون في كتب طبقات الفقهاء من الصحابة.'
  AND answer = 'من أبرزهم: عمر بن الخطاب، وعلي بن أبي طالب، وعبدالله بن مسعود، وعبدالله بن عباس، وزيد بن ثابت، ومعاذ بن جبل رضي الله عنهم جميعًا.';

-- da5ca10f | ما حكم استقالة القاضي من منصبه؟
UPDATE qa_questions SET
  answer = 'لا يُطلَق الحكمُ في ترك القاضي منصبَه، بل يُبنى على تقسيم المغني للناس في القضاء: «والنَّاسُ في القضاءِ على ثلاثةِ أضرُبٍ». فمن كان أهلًا للقضاء ويوجد غيرُه مثلُه فهو ممّن «يَجوزُ له، ولا يجبُ عليه»، فله تركُه، بل ظاهرُ كلام أحمد أنه لا يُستحبّ له الدخول فيه لِما فيه من الخطر. ومن كان يصلح للقضاء «ولا يُوجَدُ سِواهُ» فـ«فهذا يتعيَّنُ عليه»؛ «لأنَّه فرضُ كِفايةٍ، لا يقدِرُ على القيامِ به غيرُه فيتَعيَّنُ عليه» — فلا يسوغ له تركُه وتضييعُ حقوق الناس، وقد سُئل أحمد: «هلْ يأْثمُ القاضِى إذا لم يُوجَدْ غيرُه؟ قال: لا يَأْثَمُ»، وحمَل ابنُ قدامة ذلك على من لا يمكنه القيام بالواجب لظلم السلطان أو غيره، محتجًّا بنصّ أحمد الآخر: «فإنَّ أحمدَ قال: لابُدَّ للنَّاسِ مِن حاكمٍ، أتذهبُ حقوقُ النَّاسِ!». ومن لم يُحسِن القضاء ولم تجتمع فيه شروطُه فلا يجوز له الدخولُ فيه ابتداءً، فتركُه واجبٌ عليه. وأمّا ما اشتُهر من استعفاء أعيان الفقهاء فمَحمَلُه ما نصّ عليه المغني من طريقة السلف: كانوا «يَمْتَنِعونَ منه أشدَّ الامْتِناعِ»، «وكانَ يُقالُ: أعْلمُ النَّاسِ بالقَضاءِ أشدُّهُم له كَراهَةً»، ومنه: «أُريدَ أبو قِلابةَ على قضاءِ البصرَةِ، فهَرَبَ إلى اليَمامَةِ»، و«أرادَ عثمانُ رضِى اللهُ عنه تَوليةَ ابنِ عمرَ القضاءَ فَأباه». ويبقى طلبُ القضاء والسعيُ فيه مكروهًا على كلّ حال: «وعلى كلِّ حالٍ، فإنَّه يُكْرَهُ للإنسانِ طَلَبُه، والسَّعْيُ في تَحْصِيلهِ».',
  reference = 'المغني لابن قدامة، ت التركي والحلو: ج١٤/ص٦–٩ (كتاب القضاء) | الكلمات المفتاحية: استقالة القاضي',
  evidence = 'المغني ج١٤/ص٧ يقسم الناسَ في القضاء تقسيمًا حاكمًا على المسألة: «والنَّاسُ في القضاءِ على ثلاثةِ أضرُبٍ»: «منهم مَن لا يجوزُ له الدُّخولُ فيه، وهو من لا يُحسِنُه، ولم تجتَمعْ فيه شروطُه»، «ومنهم، مَن يَجوزُ له، ولا يجبُ عليه»، والثالثُ من يَصلح للقضاء ولا يوجد سواه، وحكمُه ج١٤/ص٩: «فهذا يتعيَّنُ عليه» «لأنَّه فرضُ كِفايةٍ، لا يقدِرُ على القيامِ به غيرُه فيتَعيَّنُ عليه». وفي الموضع نفسِه روايةٌ عن أحمد تُقابِلها: «هلْ يأْثمُ القاضِى إذا لم يُوجَدْ غيرُه؟ قال: لا يَأْثَمُ»، وحملَها ابن قدامة على وجهين، وردّ إطلاقَها بنصٍّ آخر لأحمد: «فإنَّ أحمدَ قال: لابُدَّ للنَّاسِ مِن حاكمٍ، أتذهبُ حقوقُ النَّاسِ!». وأصلُ الامتناع من القضاء منصوصٌ ج١٤/ص٦–٧: السلفُ «يَمْتَنِعونَ منه أشدَّ الامْتِناعِ»، و«وكانَ يُقالُ: أعْلمُ النَّاسِ بالقَضاءِ أشدُّهُم له كَراهَةً»، ومنه هربُ أبي قلابة: «أُريدَ أبو قِلابةَ على قضاءِ البصرَةِ، فهَرَبَ إلى اليَمامَةِ»، و«أرادَ عثمانُ رضِى اللهُ عنه تَوليةَ ابنِ عمرَ القضاءَ فَأباه»؛ وحكمُ طلبِه: «وعلى كلِّ حالٍ، فإنَّه يُكْرَهُ للإنسانِ طَلَبُه، والسَّعْيُ في تَحْصِيلهِ». ⚠️ وإطلاقُ ‹جائزة إذا وُجد عذر معتبر› يسقط الضربَ الثالث الذي يتعيَّن عليه القضاءُ فلا يسوغ له تركُه، فالجوابُ يلزمه التقسيمُ لا الإطلاق.',
  verification_status = 'verified'
WHERE id = 'da5ca10f-c156-481e-bee1-807aadf39e5f'
